def t(key: str, language: str = "en", **kwargs) -> str:
    if language not in TRANSLATIONS:
        raise KeyError(f"Unsupported UI language: {language}")
    if key not in TRANSLATIONS[language]:
        raise KeyError(f"Missing translation key: {language}.{key}")
    return TRANSLATIONS[language][key].format(**kwargs)


def display_label(name: str, language: str = "en") -> str:
    if language not in DISPLAY_LABELS:
        raise KeyError(f"Unsupported UI language: {language}")
    return DISPLAY_LABELS[language].get(name, name.replace("_", " ").title())


def domain_label(domain: str, language: str = "en") -> str:
    return t(f"domain.{domain}", language)


def resolve_report_language(choice: str, ui_language: str) -> str:
    resolved = ui_language if choice == "follow_ui" else choice
    if resolved not in {"en", "zh"}:
        raise ValueError(f"Unsupported report language choice: {choice}")
    return "Chinese" if resolved == "zh" else "English"
